169	    @Transactional
170	    public Xzj27 createOrderBid(String email, Long productSizeId, int bidPrice) {
171	        try {
172	
173	            validateCreateOrderBidInput(email, productSizeId, bidPrice);
174	
175	
176	            Xrd81 user = userQueryService.findByEmail(email);
177	
178	
179	            Xdh20 productSize = productSizeQueryService.findById(productSizeId)
180	                    .orElseThrow(() -> new Xrf10Exception("해당 사이즈를 찾을 수 없습니다(ID: " + productSizeId + ")"));
181	
182	
183	            Xdg64 order = orderCommandService.createOrderFromBid(user, productSize, bidPrice);
184	
185	
186	            Xzj27 orderBid = createAndSaveOrderBid(user, productSize, bidPrice, order);
187	
188	            return orderBid;
189	        } catch (Exception e) {
190	            handleOrderBidCreationException(e, "주문 입찰 생성");
191	            return null;
192	        }
193	    }
194	
195	
