295	    private Xzz58 getSaleBidAndValidate(Long saleBidId) {
296	        Xzz58 saleBid = saleBidQueryService.findById(saleBidId);
297	        if (saleBid == null) {
298	            throw new Xkt44Exception("판매 입찰을 찾을 수 없습니다(ID: " + saleBidId + ")");
299	        }
300	
301	        Xgg74 sale = saleBid.getSale();
302	        if (sale == null) {
303	            throw new Xnb95Exception("판매 입찰과 연결된 판매 정보가 없습니다.");
304	        }
305	
306	        return saleBid;
307	    }
