312	    private Xzj27 createInstantOrderBid(Xdg64 order, Xzz58 saleBid, Xgg74 sale) {
313	        Xdh20 productSize = saleBid.getProductSize();
314	
315	        Xzj27 orderBid = Xzj27.builder()
316	                .user(order.getUser())
317	                .productSize(productSize)
318	                .bidPrice(saleBid.getBidPrice())
319	                .status(Xtz73Status.MATCHED)
320	                .order(order)
321	                .sale(sale)
322	                .build();
323	
324	
325	        orderBid.assignOrder(order);
326	
327	
328	        orderBid.markAsInstantPurchase();
329	        return orderBidRepository.save(orderBid);
330	    }
