434	            Acknowledgment acknowledgment) {
435	
436	        Instant start = Instant.now();
437	
438	        try {
439	            log.info("주문 처리 이벤트 수신: 주문ID={}, 이벤트ID={}",
440	                    event.getOrderId(), event.getEventId());
441	
442	
443	            if (isOrderAlreadyProcessed(event.getOrderId())) {
