537	    private void processCompleteOrder(Xdg64 order, Xrd81 user, Xrt49RequestDto requestDto) {
538	        try {
539	            log.info("전체 주문 처리 시작: 주문ID={}", order.getId());
540	
541	
542	            Xbf54 payment = paymentCommandService.processPayment(order, user, requestDto.getPaymentRequest());
543	            order.assignPayment(payment);
544	
545	            if (!payment.isSuccess()) {
546	                throw new RuntimeException("결제 실패: " + payment.getStatus());
547	            }
548	
549	            log.info("결제 처리 완료: 주문ID={}, 결제ID={}", order.getId(), payment.getId());
550	
551	
552	            Xhx14 shipment = orderShipmentCommandService.createOrderShipment(
553	                    order,
554	                    requestDto.getReceiverName(),
555	                    requestDto.getReceiverPhone(),
556	                    requestDto.getPostalCode(),
557	                    requestDto.getAddress()
558	            );
559	            order.assignOrderShipment(shipment);
560	            log.info("배송 정보 생성 완료: 주문ID={}", order.getId());
561	
562	
563	            if (!order.getStatus().canTransitionTo(Xdg64Status.PAYMENT_COMPLETED)) {
564	                throw new RuntimeException("결제 완료 상태로 전환할 수 없습니다. 현재 상태: " + order.getStatus());
565	            }
566	            order.updateStatus(Xdg64Status.PAYMENT_COMPLETED);
567	
568	            if (requestDto.isWarehouseStorage()) {
569	
570	                Xnn94 warehouseStorage = warehouseStorageCommandService.createOrderStorage(order, user);
571	                order.assignWarehouseStorage(warehouseStorage);
572	
573	
574	                if (order.getStatus().canTransitionTo(Xdg64Status.PREPARING)) {
575	                    order.updateStatus(Xdg64Status.PREPARING);
576	                }
577	                if (order.getStatus().canTransitionTo(Xdg64Status.IN_WAREHOUSE)) {
578	                    order.updateStatus(Xdg64Status.IN_WAREHOUSE);
579	                }
580	                if (order.getStatus().canTransitionTo(Xdg64Status.COMPLETED)) {
581	                    order.updateStatus(Xdg64Status.COMPLETED);
582	                }
583	
584	                log.info("창고 보관 처리 완료: 주문ID={}", order.getId());
585	            } else {
586	
587	                if (order.getStatus().canTransitionTo(Xdg64Status.PREPARING)) {
588	                    order.updateStatus(Xdg64Status.PREPARING);
589	                }
590	                log.info("배송 준비 완료: 주문ID={}", order.getId());
591	            }
592	
593	
594	            orderRepository.save(order);
595	            log.info("전체 주문 처리 완료: 주문ID={}, 최종상태={}", order.getId(), order.getStatus());
596	
597	        } catch (Exception e) {
598	            log.error("전체 주문 처리 실패: 주문ID={}, 오류={}", order.getId(), e.getMessage(), e);
599	            throw e;
600	        }
601	    }
