607	        try {
608	            Xdg64 order = orderRepository.findById(orderId).orElse(null);
609	            if (order == null) {
610	                return false;
611	            }
612	
613	
614	            Xdg64Status currentStatus = order.getStatus();
615	            return currentStatus != Xdg64Status.PENDING_PAYMENT;
616	
617	        } catch (Exception e) {
618	            log.error("주문 중복 검사 중 오류 발생: 주문ID={}, 오류={}", orderId, e.getMessage(), e);
619	            return false;
620	        }
