public class Xdg64CommandService {

    private final Xdg64Repository orderRepository;
    private final Xbf54CommandService paymentCommandService;
    private final Xhx14CommandService orderShipmentCommandService;
    private final Xhm58CommandService orderItemCommandService;
    private final Xzj27QueryService orderBidQueryService;
    private final Xrd81QueryService userQueryService;
    private final Xnn94CommandService warehouseStorageCommandService;
    private final Xms98QueryService addressQueryService;
    private final EntityManager entityManager;











    @Transactional
    public Xdg64 createOrderFromBid(Xrd81 user, Xdh20 productSize, int bidPrice) {
        try {

            if (user == null) {
                throw new Xcz21Exception("사용자 정보가 없습니다.");
            }
            if (productSize == null) {
                throw new Xrf10Exception("상품 사이즈 정보가 없습니다.");
            }
            if (bidPrice <= 0) {
                throw new Xwh31Exception("입찰 가격은 0보다 커야 합니다. 현재 가격: " + bidPrice);
            }


            Xhm58 orderItem = orderItemCommandService.createOrderItem(null, productSize, bidPrice);


            Xdg64 order = Xdg64.builder()
                    .user(user)
                    .totalAmount(bidPrice)
                    .discountAmount(0)
                    .usedPoints(0)
                    .status(Xdg64Status.PENDING_PAYMENT)
                    .build();


            order.addOrderItem(orderItem);


            return orderRepository.save(order);
        } catch (Exception e) {
            if (e instanceof Xdg64Exception) {
                throw e;
            }
            log.error("주문 생성 중 오류 발생: {}", e.getMessage(), e);
            throw new Xbv64Exception("입찰에서 주문 생성 중 오류가 발생했습니다: " + e.getMessage(), e);
        }
    }














    @Transactional
    public void processPaymentAndShipment(Long orderId, String userEmail, Xrt49RequestDto requestDto) {
        if (orderId == null) {
            throw new Xcz21Exception("주문 ID가 없습니다.");
        }
        if (userEmail == null || userEmail.trim().isEmpty()) {
            throw new Xxf47Exception("사용자 정보가 없습니다.");
        }
        if (requestDto == null) {
            throw new Xtj87Exception("결제 및 배송 정보가 없습니다.");
        }

        try {

            Xrd81 user = userQueryService.findByEmail(userEmail);
            Xdg64 order = orderRepository.findById(orderId)
                    .orElseThrow(() -> new Xks61Exception("해당 주문을 찾을 수 없습니다(ID: " + orderId + ")"));


            if (!order.getUser().getId().equals(user.getId())) {
                throw new Xxf47Exception("해당 사용자는 이 주문을 처리할 권한이 없습니다.");
            }


            validatePaymentShipmentRequest(requestDto);

            try {

                Xbf54 payment = paymentCommandService.processPayment(order, user, requestDto.getPaymentRequest());
                order.assignPayment(payment);
            } catch (Exception e) {
                log.error("결제 처리 중 오류 발생: {}", e.getMessage(), e);
                throw new Xqj91Exception("결제 처리 중 오류가 발생했습니다: " + e.getMessage(), e);
            }

            try {

                Xhx14 shipment = orderShipmentCommandService.createOrderShipment(
                        order,
                        requestDto.getReceiverName(),
                        requestDto.getReceiverPhone(),
                        requestDto.getPostalCode(),
                        requestDto.getAddress()
                );
                order.assignOrderShipment(shipment);
            } catch (Exception e) {
                log.error("배송 정보 처리 중 오류 발생: {}", e.getMessage(), e);
                throw new Xmz95Exception("배송 정보 처리 중 오류가 발생했습니다: " + e.getMessage(), e);
            }

            try {

                if (requestDto.isWarehouseStorage()) {

                    order.updateStatus(Xdg64Status.PAYMENT_COMPLETED);
                    order.updateStatus(Xdg64Status.PREPARING);
                    order.updateStatus(Xdg64Status.IN_WAREHOUSE);


                    Xnn94 warehouseStorage = warehouseStorageCommandService.createOrderStorage(order, user);
                    order.assignWarehouseStorage(warehouseStorage);
                    order.updateStatus(Xdg64Status.COMPLETED);
                } else {

                    order.updateStatus(Xdg64Status.PAYMENT_COMPLETED);
                    order.updateStatus(Xdg64Status.PREPARING);
                }
            } catch (Xnn94Exception e) {
                log.error("창고 보관 처리 중 오류 발생: {}", e.getMessage(), e);
                throw new Xdx92Exception("창고 보관 처리 중 오류가 발생했습니다: " + e.getMessage(), e);
            } catch (Exception e) {
                log.error("주문 상태 업데이트 중 오류 발생: {}", e.getMessage(), e);
                throw new Xmv95Exception("주문 상태 업데이트 중 오류가 발생했습니다: " + e.getMessage(), e);
            }


            try {
                orderBidQueryService.findById(orderId).ifPresent(orderBid -> {
                    orderBid.updateStatus(Xtz73Status.MATCHED);
                });
            } catch (Exception e) {
                log.error("주문 입찰 상태 업데이트 중 오류 발생: {}", e.getMessage(), e);

            }
        } catch (Exception e) {
            if (e instanceof Xdg64Exception) {
                throw e;
            }
            log.error("결제 및 배송 처리 중 오류 발생: {}", e.getMessage(), e);
            throw new Xqj91Exception("결제 및 배송 처리 중 예상치 못한 오류가 발생했습니다: " + e.getMessage(), e);
        }
    }
















    @Transactional
    public Xdg64 createInstantOrder(Xrd81 buyer, Xzz58 saleBid, Long addressId,
                                    boolean isWarehouseStorage, Xbf54RequestDto paymentRequest) {
        try {

            if (buyer == null) {
                throw new Xcz21Exception("구매자 정보가 없습니다.");
            }
            if (saleBid == null) {
                throw new Xkt44Exception("판매 입찰 정보가 없습니다.");
            }
            if (addressId == null) {
                throw new Xcz21Exception("배송지 정보가 없습니다.");
            }
            if (paymentRequest == null) {
                throw new Xtj87Exception("결제 정보가 없습니다.");
            }


            Xms98ResponseDto address = addressQueryService.getAddress(buyer.getEmail(), addressId);


            Xdg64 order = Xdg64.builder()
                    .user(buyer)
                    .totalAmount(saleBid.getBidPrice())
                    .status(Xdg64Status.PENDING_PAYMENT)
                    .build();

            order = orderRepository.save(order);


            paymentRequest.setOrderId(order.getId());
            log.debug("결제 요청 정보: {}", paymentRequest);


            try {
                Xhm58 orderItem = orderItemCommandService.createOrderItem(order, saleBid.getProductSize(), saleBid.getBidPrice());
                order.addOrderItem(orderItem);
            } catch (Exception e) {
                log.error("주문 항목 생성 중 오류 발생: {}", e.getMessage(), e);
                throw new Xwg86Exception("주문 항목 생성 중 오류가 발생했습니다: " + e.getMessage(), e);
            }


            try {
                Xhx14 orderShipment = orderShipmentCommandService.createOrderShipment(
                        order,
                        address.getRecipientName(),
                        address.getPhoneNumber(),
                        address.getZipCode(),
                        address.getAddress()
                );
                order.assignOrderShipment(orderShipment);
            } catch (Exception e) {
                log.error("배송 정보 생성 중 오류 발생: {}", e.getMessage(), e);
                throw new Xmz95Exception("배송 정보 생성 중 오류가 발생했습니다: " + e.getMessage(), e);
            }

            try {

                saleBid.assignOrder(order);
                saleBid.updateStatus(com.fream.back.domain.m10.entity.Xtz73Status.MATCHED);


                entityManager.flush();
            } catch (Exception e) {
                log.error("판매 입찰 상태 업데이트 중 오류 발생: {}", e.getMessage(), e);
                throw new Xhz43Exception("판매 입찰 매칭 중 오류가 발생했습니다: " + e.getMessage(), e);
            }


            try {
                Xgg74 sale = saleBid.getSale();
                if (sale != null && sale.isWarehouseStorage()) {
                    warehouseStorageCommandService.updateWarehouseStatus(sale, Xbj14Status.ASSOCIATED_WITH_ORDER);
                }
            } catch (Xnn94Exception e) {
                log.error("창고 보관 상태 업데이트 중 오류 발생: {}", e.getMessage(), e);
                throw new Xdx92Exception("창고 보관 상태 업데이트 중 오류가 발생했습니다: " + e.getMessage(), e);
            } catch (Exception e) {
                log.error("창고 보관 상태 업데이트 중 예상치 못한 오류 발생: {}", e.getMessage(), e);
                throw new Xdx92Exception("창고 보관 상태 업데이트 중 예상치 못한 오류가 발생했습니다: " + e.getMessage(), e);
            }


            try {
                paymentCommandService.processPayment(order, buyer, paymentRequest);
            } catch (Exception e) {
                log.error("결제 처리 중 오류 발생: {}", e.getMessage(), e);
                throw new Xqj91Exception("결제 처리 중 오류가 발생했습니다: " + e.getMessage(), e);
            }

            return order;
        } catch (Exception e) {
            if (e instanceof Xdg64Exception) {
                throw e;
            }
            log.error("즉시 구매 주문 생성 중 오류 발생: {}", e.getMessage(), e);
            throw new Xbv64Exception("즉시 구매 주문 생성 중 오류가 발생했습니다: " + e.getMessage(), e);
        }
    }







    @Transactional
    public void deleteOrder(Long orderId) {
        try {

            Xdg64 order = orderRepository.findById(orderId)
                    .orElseThrow(() -> new Xks61Exception("해당 주문을 찾을 수 없습니다(ID: " + orderId + ")"));


            orderRepository.delete(order);
        } catch (Exception e) {
            if (e instanceof Xks61Exception) {
                throw e;
            }
            log.error("주문 삭제 중 오류 발생: {}", e.getMessage(), e);
            throw new Xcm26Exception("주문 삭제 중 오류가 발생했습니다: " + e.getMessage(), e);
        }
    }







    private void validatePaymentShipmentRequest(Xrt49RequestDto requestDto) {
        if (requestDto.getPaymentRequest() == null) {
            throw new Xtj87Exception("결제 정보가 없습니다.");
        }

        if (requestDto.getReceiverName() == null || requestDto.getReceiverName().trim().isEmpty()) {
            throw new Xtj87Exception("수령인 이름이 없습니다.");
        }

        if (requestDto.getReceiverPhone() == null || requestDto.getReceiverPhone().trim().isEmpty()) {
            throw new Xtj87Exception("수령인 전화번호가 없습니다.");
        }

        if (requestDto.getPostalCode() == null || requestDto.getPostalCode().trim().isEmpty()) {
            throw new Xtj87Exception("우편번호가 없습니다.");
        }

        if (requestDto.getAddress() == null || requestDto.getAddress().trim().isEmpty()) {
            throw new Xtj87Exception("주소가 없습니다.");
        }
    }
}

