 89	    public boolean canTransitionTo(Xbf54Status newStatus) {
 90	        switch (this) {
 91	            case PENDING:
 92	                return newStatus == PAID;
 93	            case PAID:
 94	                return newStatus == REFUND_REQUESTED || newStatus == REFUNDED;
