205:    private void validatePaymentInfo(Xbf54Info paymentInfo, double amount) {
206:        if (paymentInfo == null) {
207:            throw new Xbf54Exception(Xbf54ErrorCode.INVALID_CARD_INFO, "결제 수단 정보가 없습니다.");
208:        }
209:
210:        if (paymentInfo.getCardNumber() == null || paymentInfo.getCardNumber().isBlank()) {
211:            throw new Xbf54Exception(Xbf54ErrorCode.INVALID_CARD_INFO, "카드 번호는 필수 입력 값입니다.");
212:        }
213:
214:        if (paymentInfo.getExpirationDate() == null || paymentInfo.getExpirationDate().isBlank()) {
215:            throw new Xbf54Exception(Xbf54ErrorCode.INVALID_CARD_INFO, "카드 유효기간은 필수 입력 값입니다.");
216:        }
217:
218:        if (paymentInfo.getBirthDate() == null || paymentInfo.getBirthDate().isBlank()) {
219:            throw new Xbf54Exception(Xbf54ErrorCode.INVALID_CARD_INFO, "생년월일은 필수 입력 값입니다.");
220:        }
221:
222:        if (paymentInfo.getCardPassword() == null || paymentInfo.getCardPassword().isBlank()) {
223:            throw new Xbf54Exception(Xbf54ErrorCode.INVALID_CARD_INFO, "카드 비밀번호 앞 2자리는 필수 입력 값입니다.");
224:        }
225:
226:        if (amount <= 0) {
227:            throw new Xbf54Exception(Xbf54ErrorCode.INVALID_PAYMENT_AMOUNT, "결제 금액은 0보다 커야 합니다.");
228:        }
229:    }
